package io.github.leadassimilator.reticulum.datagen;

import java.util.List;
import java.util.Set;

import net.minecraft.data.DataGenerator;
import net.minecraft.data.PackOutput;
import net.minecraft.data.loot.LootTableProvider;
import net.minecraft.world.level.storage.loot.parameters.LootContextParamSets;
import net.neoforged.neoforge.data.event.GatherDataEvent;

/** {@code gradlew runData} writes block states, models, language, loot, recipes and tags to src/generated/resources. */
public final class DataGenerators {
    private DataGenerators() {
    }

    /** Everything is generated by the client data run (it has the client classes the models need). */
    public static void gatherData(GatherDataEvent.Client event) {
        DataGenerator generator = event.getGenerator();
        PackOutput output = generator.getPackOutput();
        var lookup = event.getLookupProvider();

        generator.addProvider(true, new ModModels(output));
        generator.addProvider(true, new ModLanguage(output));

        generator.addProvider(true, new LootTableProvider(output, Set.of(),
                List.of(new LootTableProvider.SubProviderEntry(ModBlockLoot::new, LootContextParamSets.BLOCK)), lookup));
        generator.addProvider(true, new ModRecipes.Runner(output, lookup));
        generator.addProvider(true, new ModBlockTags(output, lookup));
    }
}
